(()=>{'use strict';if(!window.deviceShare)return;let dialog,button,busy=false;let lastState={enabled:false,urls:[]};
function status(message){dialog.querySelector('[role=status]').textContent=message;}
function paint(state){lastState=state;const heading=document.querySelector('.topbar h2');if(heading)heading.textContent=state.enabled?'Device sharing is on':'No external API server';button.textContent=state.enabled?'Sharing on':'Share to devices';const toggle=dialog.querySelector('[data-toggle]');toggle.textContent=state.enabled?'Stop sharing':'Start sharing';const links=dialog.querySelector('[data-links]');links.replaceChildren();dialog.querySelector('[data-active]').textContent=state.enabled?'Sharing is on · Normal library only':'Sharing is off';if(state.enabled&&!state.urls.length)status('No Wi-Fi or Ethernet address found. Connect this computer to your local network, then refresh.');for(const url of state.urls){const row=document.createElement('div');row.className='device-share-link';const input=document.createElement('input');input.readOnly=true;input.value=url;input.setAttribute('aria-label','Private sharing link');input.onclick=()=>input.select();const copy=document.createElement('button');copy.type='button';copy.className='ghost-button';copy.textContent='Copy link';copy.onclick=async()=>{try{await window.deviceShare.copy(url);status('Link copied. Send it to your phone and open it in the browser.');}catch{status('Could not copy the link. Refresh addresses and try again.');}};row.append(input,copy);links.append(row);}}
async function refresh(){try{paint(await window.deviceShare.state());}catch{status('Sharing status is unavailable. Restart MLA+ and try again.');}}
function mount(){const actions=document.querySelector('.topbar-actions');if(!actions||actions.querySelector('[data-device-share-button]'))return;button=document.createElement('button');button.type='button';button.className='ghost-button';button.dataset.deviceShareButton='';button.textContent=lastState.enabled?'Sharing on':'Share to devices';button.onclick=()=>{if(!dialog)makeDialog();status('');dialog.showModal();refresh();};actions.prepend(button);}
function makeDialog(){dialog=document.createElement('dialog');dialog.className='device-share-dialog';dialog.setAttribute('aria-labelledby','device-share-title');dialog.innerHTML='<div class="device-share-heading"><h2 id="device-share-title">Watch on your phone</h2><button type="button" class="ghost-button" data-close aria-label="Close device sharing">Close</button></div><p>Browse and stream your Normal library on a phone, tablet, or another computer. Your files stay in their original folders.</p><p data-active></p><ol><li>Connect both devices to the same Wi-Fi.</li><li>Start sharing and copy the private link below.</li><li>Open the link in your other device’s browser.</li></ol><div data-links></div><p class="device-share-hint">Keep MLA+ open and the video’s disk connected. Anyone with the link on your local network can watch and add subtitles. Stopping sharing disconnects viewers; restarting creates a new link.</p><p class="device-share-hint">If Windows asks about network access, allow Private networks. Guest Wi-Fi may block devices from connecting. Some video formats need a compatible player such as VLC.</p><p role="status" aria-live="polite"></p><div class="device-share-actions"><button type="button" class="primary-button" data-toggle>Start sharing</button><button type="button" class="ghost-button" data-refresh>Refresh addresses</button></div>';
dialog.querySelector('[data-close]').onclick=()=>dialog.close();dialog.querySelector('[data-refresh]').onclick=refresh;dialog.querySelector('[data-toggle]').onclick=async()=>{if(busy)return;busy=true;const toggle=dialog.querySelector('[data-toggle]');toggle.disabled=true;status('');try{paint(await(lastState.enabled?window.deviceShare.stop():window.deviceShare.start()));status(lastState.enabled?'Sharing started. Open the private link on your other device.':'Sharing stopped. Previous links no longer work.');}catch(error){status('Could not change sharing: '+error.message);}finally{busy=false;toggle.disabled=false;}};document.body.append(dialog);}
new MutationObserver(mount).observe(document.documentElement,{childList:true,subtree:true});mount();})();
